70:function challengeCount(){return evidence.filter(e=>e.found).length+riddleSolved}function collect(){let got=false;for(const e of evidence){if(!e.found&&Math.hypot(player.position.x-e.mesh.position.x,player.position.z-e.mesh.position.z)<1.65){e.found=true;e.mesh.visible=false;if(e.type==='clue')clues++;got=true;$('#collectible-label').textContent=`GOTHAM CHALLENGES ${String(challengeCount()).padStart(2,'0')} / 50`;toast(`${e.type==='trophy'?'RIDDLER TROPHY':'HIDDEN CLUE'} ${challengeCount()} / 50 RECOVERED`);break}}for(const r of riddles)if(!r.solved){r.mesh.rotation.y+=.01}if(got){updateObjective();progress()}}
